      a: { ru: 'a = int(input("Первое число: "))\nb = int(input("Второе число: "))\nprint("Сумма:", a + b)\nprint("Разность:", a - b)\nprint("Произведение:", a * b)',
           kk: 'a = int(input("Бірінші сан: "))\nb = int(input("Екінші сан: "))\nprint("Қосындысы:", a + b)\nprint("Айырмасы:", a - b)\nprint("Көбейтіндісі:", a * b)' },
