      a: { ru: 'with open("hobby.txt", "w", encoding="utf-8") as f:\n    f.write("футбол\\n")\n    f.write("шахматы\\n")\n    f.write("программирование\\n")',
           kk: 'with open("hobby.txt", "w", encoding="utf-8") as f:\n    f.write("футбол\\n")\n    f.write("шахмат\\n")\n    f.write("бағдарламалау\\n")' },
